changeSet.sql:

if exists (select 1 from INFORMATION_SCHEMA.TABLES where table_name = 'ObjectStyle')
begin
	EXEC sp_rename 'dbo.ObjectStyle', 'ObjectStyle-retired';   
end

changeSet.rollback:

if exists (select 1 from INFORMATION_SCHEMA.TABLES where table_name = 'ObjectStyle-retired')
begin
	EXEC sp_rename 'dbo.ObjectStyle-retired', 'ObjectStyle';  
end
